function formatKstDateTime(value) {
  if (!value) return '-';
  var s = String(value);
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(s)) return s;  /* 이미 tz 없는 로컬 형식 */
  var d = new Date(s);
  if (isNaN(d.getTime())) return s.replace('T', ' ').replace('Z', '').slice(0, 19);
  var kst = new Date(d.getTime() + 9 * 60 * 60 * 1000);
  function p(n) { return String(n).padStart(2, '0'); }
  return kst.getUTCFullYear() + '-' + p(kst.getUTCMonth() + 1) + '-' + p(kst.getUTCDate())
    + ' ' + p(kst.getUTCHours()) + ':' + p(kst.getUTCMinutes()) + ':' + p(kst.getUTCSeconds());
}
